        ScrollRect reading;Button checkButton,primary,retryButton,readerRetry;ArchiveGraphMapGraphic map;
        readonly Button[] degreeButtons=new Button[7];readonly TMP_Text[] mapLabels=new TMP_Text[6];readonly Image[] progress=new Image[5];
        int revision=-1;string readingKey="";Vector2 screen;Rect safe;float canvasScale;Vector3 previousRunner=Vector3.one*999;float nextMap;
        static readonly Color Ink=new Color(.16f,.11f,.07f),Teal=new Color(.08f,.36f,.35f),Red=new Color(.75f,.13f,.10f);
