        void Build(){
            objective=Box("T9_Compact_Graph_Objective",transform,Vector2.one,new Vector2(440,248),owner.statusArt);objective.pivot=Vector2.one;
            title=Label("Challenge_Progress",objective,22,owner.headingFont,Ink,new Vector2(.06f,.82f),new Vector2(.73f,.94f));timer=Label("Shared_T9_Timer",objective,23,owner.headingFont,Teal,new Vector2(.76f,.82f),new Vector2(.94f,.94f));timer.alignment=TextAlignmentOptions.MidlineRight;
            stage=Label("Graph_Activity",objective,22,owner.headingFont,Ink,new Vector2(.06f,.66f),new Vector2(.94f,.82f));summary=Label("Recorded_Route",objective,18,owner.textFont,Teal,new Vector2(.06f,.37f),new Vector2(.94f,.66f));cue=Label("Nearby_Action",objective,17,owner.textFont,Teal,new Vector2(.06f,.25f),new Vector2(.94f,.38f));
            MakeButton(objective,"Read / Map",Read,new Vector2(.19f,.135f),new Vector2(125,50),19);retryButton=MakeButton(objective,"Retry",Retry,new Vector2(.49f,.135f),new Vector2(100,50),20);retryLabel=retryButton.GetComponentInChildren<TMP_Text>();checkButton=MakeButton(objective,"Confirm",Submit,new Vector2(.79f,.135f),new Vector2(142,50),21);
