            reader=Box("T9_Path_Of_Connections_Reader",transform,new Vector2(.5f,.52f),new Vector2(1120,800),owner.panelArt);
            readerTitle=Label("Topic_And_Challenge",reader,28,owner.headingFont,Ink,new Vector2(.055f,.845f),new Vector2(.73f,.95f));MakeButton(reader,"Close",owner.Close,new Vector2(.85f,.90f),new Vector2(230,82),27);
            readerTimer=Label("Shared_Clock",reader,23,owner.textFont,Teal,new Vector2(.54f,.795f),new Vector2(.94f,.835f));readerTimer.alignment=TextAlignmentOptions.MidlineRight;
