            mapCaption=Label("Graph_Legend",reader,19,owner.textFont,Teal,new Vector2(.61f,.745f),new Vector2(.94f,.80f));mapCaption.text="Orange: edge · Blue: walked";
            var viewport=Rect("Graph_Reading",reader,new Vector2(.065f,.30f),new Vector2(.58f,.745f));viewport.gameObject.AddComponent<RectMask2D>();viewport.gameObject.AddComponent<Image>().color=new Color(.07f,.29f,.28f,.055f);reading=viewport.gameObject.AddComponent<ScrollRect>();reading.horizontal=false;reading.movementType=ScrollRect.MovementType.Clamped;reading.scrollSensitivity=35;
