            for(int i=0;i<mapLabels.Length;i++){mapLabels[i]=Label("Vertex_Label_"+i,mapRect,18,owner.headingFont,new Color(1,.95f,.8f),new Vector2(.5f,.5f),new Vector2(.5f,.5f));mapLabels[i].rectTransform.sizeDelta=new Vector2(40,32);mapLabels[i].alignment=TextAlignmentOptions.Center;}
            for(int i=0;i<7;i++){int index=i;degreeButtons[i]=MakeButton(reader,i.ToString(),()=>owner.session.Request(8,ArchiveAction.Select,index),new Vector2(.63f+i*.048f,.285f),new Vector2(48,46),23);}
