        }
        public void Open(){reader.gameObject.SetActive(true);revision=-1;Refresh();}
        public void Close(){if(reader!=null)reader.gameObject.SetActive(false);}
        void Read()=>owner.Open(owner.session.stations[8]);
        void Retry()=>owner.session.Request(8,ArchiveAction.RetryRoute);
        void Submit(){if(ArchiveGraphPresentation.ReadyToCheck(owner.session))owner.session.Request(8,ArchiveAction.Submit);}
        void Primary(){var s=owner.session.State.stations[8];if(s.phase==0)owner.session.Request(8,ArchiveAction.Start);else if(s.phase==1)Submit();else owner.Close();}
        void Update(){if(owner==null||owner.session==null||!owner.session.Ready)return;var session=owner.session;var s=session.State.stations[8];var q=session.Question(8);bool near=Player.LocalInstance!=null&&session.CanAct(session.LocalActor)&&Time.timeScale>0&&Vector3.Distance(Player.LocalInstance.transform.position,session.stations[8].transform.position)<34;objective.gameObject.SetActive(near&&owner.ReadingStation==null);if(!near){if(IsOpen)owner.Close();return;}
            if(screen!=new Vector2(Screen.width,Screen.height)||safe!=Screen.safeArea||!Mathf.Approximately(canvasScale,owner.GetComponent<Canvas>().scaleFactor))PositionObjective();if(revision!=session.State.revision){revision=session.State.revision;Refresh();}
            int seconds=Mathf.CeilToInt(session.TimerRemaining(s));string time=(seconds/60).ToString("00")+":"+(seconds%60).ToString("00");timer.text=time;readerTimer.text="TEAM TIME  "+time+(s.phase==0&&!s.timerExpired?" · paused at Book":"");timer.color=readerTimer.color=s.timerExpired||s.timerRunning&&seconds<=30?Red:Teal;
            bool unlocked=string.IsNullOrEmpty(session.TopicLockNotice(8)),active=unlocked&&s.phase==1,degree=q.graph.type==GraphChallengeType.Degree;bool canCheck=active&&ArchiveGraphPresentation.ReadyToCheck(session)&&session.Near(session.LocalActor,8,Vector3.zero,14);checkButton.interactable=canCheck;primary.interactable=s.phase==2||canCheck||unlocked&&s.phase==0&&session.Near(session.LocalActor,8,ArchiveTopicStation.BookPosition,ArchiveTopicSession.BookUseRadius);bool retry=active&&(degree?s.selection>=0:session.CanUseGraphStart(session.LocalActor));retryButton.interactable=readerRetry.interactable=retry;
            for(int i=0;i<degreeButtons.Length;i++)degreeButtons[i].interactable=active&&degree&&session.Near(session.LocalActor,8,Vector3.zero,14);
            cue.text=!unlocked?"Another topic is active":s.phase!=1?"Book Statue · Hand / E":degree?"Count the purple vertex's edges":s.routeActor==0?"Stand on START · Hand / E to claim":!s.continuous?"Return to START · Retry":s.routeActor==session.LocalActor?"Stay on paths · Confirm at goal":"Runner: "+session.ActorName(s.routeActor);
            if(IsOpen&&Time.unscaledTime>=nextMap){nextMap=Time.unscaledTime+.1f;var runner=s.routeActor==0?Vector3.one*999:session.GraphFeet(s.routeActor);if((runner-previousRunner).sqrMagnitude>.0025f){previousRunner=runner;UpdateMap(q,s);}}
        }
        void Refresh(){var session=owner.session;if(!session.Ready)return;var s=session.State.stations[8];var q=session.Question(8);bool display=s.phase==1||s.timerExpired,degree=q.graph.type==GraphChallengeType.Degree;
            title.text=s.phase==2?"T9 · TEAM COMPLETE 5 / 5":"T9 · CHALLENGE "+(s.round+1)+" / 5";stage.text=s.phase==2?"Path of Connections restored":s.timerExpired?"Time up · work kept":s.phase==0?"Read the Book to continue":q.title;summary.text=display?(degree?"Focus: "+q.graph.Vertex(q.graph.degreeVertex).label+" · Degree = "+(s.selection<0?"?":s.selection.ToString()):(q.graph.type==GraphChallengeType.Cycle?"Close at "+ArchiveTopicQuestions.GraphLabel(q,q.graph.start):"Start "+ArchiveTopicQuestions.GraphLabel(q,q.graph.start)+" → Goal "+ArchiveTopicQuestions.GraphLabel(q,q.graph.destination))+"\n"+ArchiveGraphPresentation.RouteText(q,s)):s.phase==2?"Five shared graph challenges complete":"Five challenges · 10-minute shared clock";
            readerTitle.text="T9  GRAPHS\n"+(s.phase==2?"Team complete · 5 / 5":"Challenge "+(s.round+1)+" / 5 · "+q.title);
            body.text=display?q.prompt+"\n\n"+q.instructions+"\n\n"+(degree?"CURRENT DEGREE\n"+(s.selection<0?"No answer selected.":s.selection.ToString()):"RECORDED ROUTE\n"+ArchiveGraphPresentation.RouteText(q,s)+"\nRunner: "+(s.routeActor==0?"Unclaimed":session.ActorName(s.routeActor))+"\n"+(s.continuous?"Follow the connecting paths.":s.routeReason))+"\n\nLESSON\n"+q.graph.lesson+"\n\nWrong Confirm: one submitting-player mistake and ten seconds deducted. Current work stays. Reading keeps the world and timer running.":s.phase==2?"The team restored the Path of Connections.\n\n"+s.reveal:s.round==0?"Five challenges: cross an edge, count vertex degree, find a simple path, follow directed edges, and close a cycle.\n\nRead at the Book to start the shared ten-minute clock. The remaining time pauses only at solved Book gates.\n\nFor walking challenges, stand on the green start rune and use Hand / E or Claim / Retry. One teammate runs the route; everyone can watch the live map. Only actual movement along allowed connecting paths records progress.\n\nOther players and both monsters remain free to cross the arena.":s.reveal+"\n\nSolved challenge kept. The clock is paused. Read at the Book to continue.";
            string key=session.State.seed+":"+s.round+":"+s.phase;if(key!=readingKey){readingKey=key;Canvas.ForceUpdateCanvases();reading.verticalNormalizedPosition=1;}
            for(int i=0;i<7;i++){degreeButtons[i].gameObject.SetActive(display&&degree);var colors=degreeButtons[i].colors;colors.normalColor=s.selection==i?new Color(.72f,1,.89f):Color.white;degreeButtons[i].colors=colors;}
            retryLabel.text=degree?"Clear":s.routeActor==0?"Claim":"Retry";readerRetry.GetComponentInChildren<TMP_Text>().text=degree?"Clear choice":"Claim / Retry";primaryLabel.text=s.phase==2?"Explore":s.phase==1?"Confirm answer":s.timerExpired?"Retry at Book":s.round==0?"Begin at Book":"Next at Book";feedback.text=session.TopicLockNotice(8);if(string.IsNullOrEmpty(feedback.text))feedback.text=string.IsNullOrEmpty(s.routeReason)?s.feedback:s.routeReason;feedback.color=!s.continuous&&s.route.Count>0||s.lastAnswerResult<0&&s.phase==1?Red:Ink;for(int i=0;i<5;i++)progress[i].color=i<s.round?Teal:new Color(.2f,.4f,.35f,.2f);UpdateMap(q,s);
        }
        void UpdateMap(ArchiveQuestion q,ArchiveStationState s){Canvas.ForceUpdateCanvases();map.Show(q,s,s.routeActor==0?Vector3.zero:owner.session.GraphFeet(s.routeActor),s.routeActor!=0);for(int i=0;i<mapLabels.Length;i++){mapLabels[i].gameObject.SetActive(i<q.nodes.Length);if(i<q.nodes.Length){mapLabels[i].text=ArchiveGraphPresentation.Label(q,i);mapLabels[i].rectTransform.anchoredPosition=map.MapPoint(q.nodes[i])+Vector2.up*27;}}}
        void PositionObjective(){Canvas.ForceUpdateCanvases();screen=new Vector2(Screen.width,Screen.height);safe=Screen.safeArea;canvasScale=Mathf.Max(.01f,owner.GetComponent<Canvas>().scaleFactor);float right=(Screen.width-safe.xMax)/canvasScale+28,top=(Screen.height-safe.yMax)/canvasScale+224;var corners=new Vector3[4];if(healthControl!=null){healthControl.GetWorldCorners(corners);top=Mathf.Max(top,(Screen.height-corners.Min(p=>p.y))/canvasScale+12);}float height=248;if(jumpControl!=null){jumpControl.GetWorldCorners(corners);height=Mathf.Clamp((Screen.height-top*canvasScale-corners.Max(p=>p.y))/canvasScale-16,210,248);}objective.anchoredPosition=new Vector2(-right,-top);objective.sizeDelta=new Vector2(440,height);}
        Button MakeButton(Transform parent,string value,UnityEngine.Events.UnityAction callback,Vector2 anchor,Vector2 size,int fontSize){var r=Box(value.Replace(' ','_'),parent,anchor,size,owner.buttonArt);var button=r.gameObject.AddComponent<Button>();button.onClick.AddListener(callback);r.GetComponent<Image>().raycastTarget=true;var colors=button.colors;colors.highlightedColor=new Color(1,.96f,.82f);colors.pressedColor=new Color(.76f,.83f,.77f);colors.disabledColor=new Color(.57f,.57f,.57f);button.colors=colors;var text=Label("Label",r,fontSize,owner.headingFont,new Color(1,.95f,.8f),new Vector2(.06f,.12f),new Vector2(.94f,.88f));text.text=value;text.alignment=TextAlignmentOptions.Center;return button;}
        TMP_Text Label(string name,Transform parent,float size,TMP_FontAsset font,Color color,Vector2 min,Vector2 max){var r=Rect(name,parent,min,max);var text=r.gameObject.AddComponent<TextMeshProUGUI>();text.font=font;text.fontSize=size;text.fontSizeMax=size;text.fontSizeMin=size-3;text.enableAutoSizing=true;text.richText=false;text.color=color;text.raycastTarget=false;text.alignment=TextAlignmentOptions.MidlineLeft;text.overflowMode=TextOverflowModes.Ellipsis;return text;}
        RectTransform Box(string name,Transform parent,Vector2 anchor,Vector2 size,Sprite sprite){var r=Rect(name,parent,anchor,anchor);r.sizeDelta=size;var image=r.gameObject.AddComponent<Image>();image.sprite=sprite;image.type=Image.Type.Sliced;image.pixelsPerUnitMultiplier=4.5f;image.raycastTarget=false;return r;}
        static RectTransform Rect(string name,Transform parent,Vector2 min,Vector2 max){var r=new GameObject(name,typeof(RectTransform)).GetComponent<RectTransform>();r.SetParent(parent,false);r.anchorMin=min;r.anchorMax=max;r.offsetMin=r.offsetMax=Vector2.zero;return r;}
    }
